  btn.Text = "  " .. name .. ": [OFF]"     btn.TextColor3 = Color3.fromRGB(200, 200, 200)     btn.TextSize = 14     btn.Font = Enum.Font.GothamMedium     btn.TextXAlignment = Enum.TextXAlignment.Left     btn.Parent = ContentContainer      local corner = Instance.new("UICorner")     corner.CornerRadius = UDim.new(0, 6)     corner.Parent = btn      local stroke = Instance.new("UIStroke")     stroke.Color = Color3.fromRGB(40, 40, 40)     stroke.Thickness = 1     stroke.Parent = btn      local active = false     btn.MouseButton1Click:Connect(function()         active = not active         if active then             btn.Text = "  " .. name .. ": [ON]"             btn.TextColor3 = Color3.fromRGB(255, 255, 255)             stroke.Color = Color3.fromRGB(220, 20, 60)         else             btn.Text = "  " .. name .. ": [OFF]"             btn.TextColor3 = Color3.fromRGB(200, 200, 200)             stroke.Color = Color3.fromRGB(40, 40, 40)         end         callback(active)     end)     return btn end  -- Feature States local aimbotEnabled = false local autoGetGun = false local autoCollectCoins = false local autoFarmCoins = false local autoThrowKnife = false local camLockEnabled = false local wallHopEnabled = false local flingEnabled = false local espEnabled = false local antiFlingEnabled = false local notifyRolesEnabled = false local customSpeedVal = 16 local flingTargetName = ""  -- Speed Configuration Section local SpeedContainer = Instance.new("Frame") SpeedContainer.Size = UDim2.new(1, 0, 0, 50) SpeedContainer.BackgroundColor3 = Color3.fromRGB(20, 20, 20) SpeedContainer.BackgroundTransparency = 0.3 SpeedContainer.BorderSizePixel = 0 SpeedContainer.Parent = ContentContainer  local SC_Corner = Instance.new("UICorner") SC_Corner.CornerRadius = UDim.new(0, 6) SC_Corner.Parent = SpeedContainer  local SC_Stroke = Instance.new("UIStroke") SC_Stroke.Color = Color3.fromRGB(40, 40, 40) SC_Stroke.Thickness = 1 SC_Stroke.Parent = SpeedContainer  local SpeedLabel = Instance.new("TextLabel") SpeedLabel.Size = UDim2.new(0, 160, 1, 0) SpeedLabel.Position = UDim2.new(0, 10, 0, 0) SpeedLabel.BackgroundTransparency = 1 SpeedLabel.Text = "Custom WalkSpeed:" SpeedLabel.TextColor3 = Color3.fromRGB(255, 255, 255) SpeedLabel.TextSize = 13 SpeedLabel.Font = Enum.Font.GothamBold SpeedLabel.TextXAlignment = Enum.TextXAlignment.Left SpeedLabel.Parent = SpeedContainer  local SpeedTextBox = Instance.new("TextBox") SpeedTextBox.Size = UDim2.new(0, 100, 0, 32) SpeedTextBox.Position = UDim2.new(1, -110, 0.5, -16) SpeedTextBox.BackgroundColor3 = Color3.fromRGB(30, 30, 30) SpeedTextBox.Text = "16" SpeedTextBox.TextColor3 = Color3.fromRGB(255, 255, 255) SpeedTextBox.TextSize = 14 SpeedTextBox.Font = Enum.Font.GothamBold SpeedTextBox.Parent = SpeedContainer  local STB_Corner = Instance.new("UICorner") STB_Corner.CornerRadius = UDim.new(0, 4) STB_Corner.Parent = SpeedTextBox  SpeedTextBox.FocusLost:Connect(function()     local val = tonumber(SpeedTextBox.Text)     if val then customSpeedVal = val end end)  -- Toggles & UI Elements createToggle("Aimbot (Shoot Murderer)", function(state) aimbotEnabled = state end) createToggle("Auto Get Gun", function(state) autoGetGun = state end) createToggle("Auto Collect Coins", function(state) autoCollectCoins = state end) createToggle("Auto Farm Coins (Tween)", function(state) autoFarmCoins = state end) createToggle("Auto Throw Knife", function(state) autoThrowKnife = state end) createToggle("Cam Lock Murderer", function(state) camLockEnabled = state end) createToggle("Wall Hop", function(state) wallHopEnabled = state end) createToggle("Role ESP (Murderer: Red | Sheriff: Blue | Innocent: Yellow)", function(state) espEnabled = state end) createToggle("Anti-Fling Protection", function(state) antiFlingEnabled = state end) createToggle("Notify Murderer & Sheriff", function(state) notifyRolesEnabled = state end)  -- Fling Config Section local FlingContainer = Instance.new("Frame") FlingContainer.Size = UDim2.new(1, 0, 0, 75) FlingContainer.BackgroundColor3 = Color3.fromRGB(20, 20, 20) FlingContainer.BackgroundTransparency = 0.3 FlingContainer.BorderSizePixel = 0 FlingContainer.Parent = ContentContainer  local FlingCorner = Instance.new("UICorner") FlingCorner.CornerRadius = UDim.new(0, 6) FlingCorner.Parent = FlingContainer  local FlingStroke = Instance.new("UIStroke") FlingStroke.Color = Color3.fromRGB(40, 40, 40) FlingStroke.Thickness = 1 FlingStroke.Parent = FlingContainer  local FlingLabel = Instance.new("TextLabel") FlingLabel.Size = UDim2.new(1, -12, 0, 25) FlingLabel.Position = UDim2.new(0, 6, 0, 4) FlingLabel.BackgroundTransparency = 1 FlingLabel.Text = "Target Fling Username:" FlingLabel.TextColor3 = Color3.fromRGB(220, 20, 20) FlingLabel.TextSize = 13 FlingLabel.Font = Enum.Font.GothamBold FlingLabel.TextXAlignment = Enum.TextXAlignment.Left FlingLabel.Parent = FlingContainer  local FlingTextBox = Instance.new("TextBox") FlingTextBox.Size = UDim2.new(1, -110, 0, 32) FlingTextBox.Position = UDim2.new(0, 6, 0, 34) FlingTextBox.BackgroundColor3 = Color3.fromRGB(30, 30, 30) FlingTextBox.Text = "" FlingTextBox.PlaceholderText = "Enter target name..." FlingTextBox.TextColor3 = Color3.fromRGB(255, 255, 255) FlingTextBox.TextSize = 13 FlingTextBox.Font = Enum.Font.Gotham FlingTextBox.Parent = FlingContainer  local TBakCorner = Instance.new("UICorner") TBakCorner.CornerRadius = UDim.new(0, 4) TBakCorner.Parent = FlingTextBox  FlingTextBox.FocusLost:Connect(function()     flingTargetName = FlingTextBox.Text end)  local FlingExecBtn = Instance.new("TextButton") FlingExecBtn.Size = UDim2.new(0, 95, 0, 32) FlingExecBtn.Position = UDim2.new(1, -101, 0, 34) FlingExecBtn.BackgroundColor3 = Color3.fromRGB(180, 20, 20) FlingExecBtn.Text = "Fling [OFF]" FlingExecBtn.TextColor3 = Color3.fromRGB(255, 255, 255) FlingExecBtn.TextSize = 13 FlingExecBtn.Font = Enum.Font.GothamBold FlingExecBtn.Parent = FlingContainer  local FlingBtnCorner = Instance.new("UICorner") FlingBtnCorner.CornerRadius = UDim.new(0, 4) FlingBtnCorner.Parent = FlingExecBtn  FlingExecBtn.MouseButton1Click:Connect(function()     flingEnabled = not flingEnabled     if flingEnabled then         FlingExecBtn.Text = "Fling [ON]"         FlingExecBtn.BackgroundColor3 = Color3.fromRGB(0, 180, 60)     else         FlingExecBtn.Text = "Fling [OFF]"         FlingExecBtn.BackgroundColor3 = Color3.fromRGB(180, 20, 20)     end end)  -- Kill All Button (Murderer specific) local KillAllBtn = Instance.new("TextButton") KillAllBtn.Size = UDim2.new(1, 0, 0, 38) KillAllBtn.BackgroundColor3 = Color3.fromRGB(120, 10, 10) KillAllBtn.Text = "Kill All (If Murderer)" KillAllBtn.TextColor3 = Color3.fromRGB(255, 255, 255) KillAllBtn.TextSize = 14 KillAllBtn.Font = Enum.Font.GothamBold KillAllBtn.Parent = ContentContainer  local KACorner = Instance.new("UICorner") KACorner.CornerRadius = UDim.new(0, 6) KACorner.Parent = KillAllBtn  KillAllBtn.MouseButton1Click:Connect(function()     pcall(function()         for _, p in ipairs(Players:GetPlayers()) do             if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then                 LocalPlayer.Character.HumanoidRootPart.CFrame = p.Character.HumanoidRootPart.CFrame                 task.wait(0.1)             end         end     end) end)  -- External Floating Dock local FloatingDock = Instance.new("Frame") FloatingDock.Size = UDim2.new(0, 44, 0, 220) FloatingDock.Position = UDim2.new(0, 10, 0.3, 0) FloatingDock.BackgroundColor3 = Color3.fromRGB(15, 15, 15) FloatingDock.BackgroundTransparency = 0.2 FloatingDock.BorderSizePixel = 0 FloatingDock.Active = true FloatingDock.Draggable = true FloatingDock.Parent = ScreenGui  local FDCorner = Instance.new("UICorner") FDCorner.CornerRadius = UDim.new(0, 8) FDCorner.Parent = FloatingDock  local FDStroke = Instance.new("UIStroke") FDStroke.Color = Color3.fromRGB(200, 20, 20) FDStroke.Thickness = 1.5 FDStroke.Parent = FloatingDock  local FDLayout = Instance.new("UIListLayout") FDLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center FDLayout.VerticalAlignment = Enum.VerticalAlignment.Center FDLayout.SortOrder = Enum.SortOrder.LayoutOrder FDLayout.Padding = UDim.new(0, 6) FDLayout.Parent = FloatingDock  local function createExternalIcon(text, onClick)     local b = Instance.new("TextButton")     b.Size = UDim2.new(0, 32, 0, 32)     b.BackgroundColor3 = Color3.fromRGB(30, 30, 30)     b.Text = text     b.TextColor3 = Color3.fromRGB(255, 255, 255)     b.TextSize = 9     b.Font = Enum.Font.GothamBold     b.Parent = FloatingDock          local c = Instance.new("UICorner")     c.CornerRadius = UDim.new(0, 6)     c.Parent = b          b.MouseButton1Click:Connect(onClick)     return b end  createExternalIcon("SHOOT", function()     pcall(function()         for _, p in ipairs(Players:GetPlayers()) do             if p ~= LocalPlayer and p.Character and (p.Character:FindFirstChild("Knife") or p.Backpack:FindFirstChild("Knife")) then                 if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then                     Camera.CFrame = CFrame.new(Camera.CFrame.Position, p.Character.HumanoidRootPart.Position)                 end             end         end     end) end)  createExternalIcon("CAM", function() camLockEnabled = not camLockEnabled end) createExternalIcon("GUN", function() autoGetGun = not autoGetGun end) createExternalIcon("HOP", function() wallHopEnabled = not wallHopEnabled end) createExternalIcon("UI", function() MainFrame.Visible = not MainFrame.Visible end)  -- Movable Shoot Widget Circle local ShootCircle = Instance.new("TextButton") ShootCircle.Size = UDim2.new(0, 55, 0, 55) ShootCircle.Position = UDim2.new(0, 60, 0.7, 0) ShootCircle.BackgroundColor3 = Color3.fromRGB(0, 0, 0) ShootCircle.BackgroundTransparency = 0.2 ShootCircle.Text = "SHOOT" ShootCircle.TextColor3 = Color3.fromRGB(220, 20, 60) ShootCircle.TextSize = 11 ShootCircle.Font = Enum.Font.GothamBold ShootCircle.Active = true ShootCircle.Draggable = true ShootCircle.Parent = ScreenGui  local SCirCorner = Instance.new("UICorner") SCirCorner.CornerRadius = UDim.new(1, 0) SCirCorner.Parent = ShootCircle  local SCirStroke = Instance.new("UIStroke") SCirStroke.Color = Color3.fromRGB(220, 20, 60) SCirStroke.Thickness = 2 SCirStroke.Parent = ShootCircle  ShootCircle.MouseButton1Click:Connect(function()     pcall(function()         for _, p in ipairs(Players:GetPlayers()) do             if p ~= LocalPlayer and p.Character and (p.Character:FindFirstChild("Knife") or p.Backpack:FindFirstChild("Knife")) then                 if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then                     Camera.CFrame = CFrame.new(Camera.CFrame.Position, p.Character.HumanoidRootPart.Position)                 end             end         end     end) end)  local minimized = false MinMaxBtn.MouseButton1Click:Connect(function()     minimized = not minimized     if minimized then         ContentContainer.Visible = false         MainFrame.Size = UDim2.new(0, 500, 0, 40)         MinMaxBtn.Text = "+"     else         ContentContainer.Visible = true         MainFrame.Size = UDim2.new(0, 500, 0, 380)         MinMaxBtn.Text = "-"     end end)  -- Utility Functions local function getMurderer()     for _, p in ipairs(Players:GetPlayers()) do         if p ~= LocalPlayer and p.Character and (p.Character:FindFirstChild("Knife") or p.Backpack:FindFirstChild("Knife")) then             return p.Character         end     end     return nil end  local function getGunDrop()     for _, v in ipairs(Workspace:GetChildren()) do         if v.Name == "GunDrop" or v.Name == "Gun" then             return v         end     end     return nil end  -- Core RenderStepped Loops RunService.RenderStepped:Connect(function()     pcall(function()         if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then             LocalPlayer.Character.Humanoid.WalkSpeed = customSpeedVal         end     end)      if antiFlingEnabled then         pcall(function()             if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then                 LocalPlayer.Character.HumanoidRootPart.AssemblyLinearVelocity = Vector3.new(0, LocalPlayer.Character.HumanoidRootPart.AssemblyLinearVelocity.Y, 0)                 LocalPlayer.Character.HumanoidRootPart.AssemblyAngularVelocity = Vector3.new(0, 0, 0)             end         end)     end      if camLockEnabled then         pcall(function()             local murdChar = getMurderer()             if murdChar and murdChar:FindFirstChild("HumanoidRootPart") then                 Camera.CFrame = CFrame.new(Camera.CFrame.Position, murdChar.HumanoidRootPart.Position)             end         end)     end      if aimbotEnabled then         pcall(function()             local murdChar = getMurderer()             if murdChar and murdChar:FindFirstChild("HumanoidRootPart") then                 Camera.CFrame = CFrame.new(Camera.CFrame.Position, murdChar.HumanoidRootPart.Position)             end         end)     end      if autoGetGun then         pcall(function()             local gun = getGunDrop()             if gun and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then                 LocalPlayer.Character.HumanoidRootPart.CFrame = gun.CFrame             end         end)     end      if wallHopEnabled then         pcall(function()             local char = LocalPlayer.Character             if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChild("Humanoid") then                 local hrp = char.HumanoidRootPart                 local ray = Workspace:Raycast(hrp.Position, hrp.CFrame.LookVector * 3)                 if ray and char.Humanoid:GetState() == Enum.HumanoidStateType.Freefall then                     hrp.AssemblyLinearVelocity = Vector3.new(hrp.AssemblyLinearVelocity.X, 50, hrp.AssemblyLinearVelocity.Z)                 end             end         end)     end      if flingEnabled and flingTargetName ~= "" then         pcall(function()             local targetPlayer = nil             for _, p in ipairs(Players:GetPlayers()) do                 if string.sub(string.lower(p.Name), 1, string.len(flingTargetName)) == string.lower(flingTargetName) then                     targetPlayer = p                     break                 end             end             if targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart") then                 local tHrp = targetPlayer.Character.HumanoidRootPart                 local myHrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")                 if myHrp then                     myHrp.CFrame = tHrp.CFrame * CFrame.new(math.random(-2,2), 0, math.random(-2,2))                     myHrp.AssemblyLinearVelocity = Vector3.new(99999, 99999, 99999)                 end             end         end)     end      if autoCollectCoins or autoFarmCoins then         pcall(function()             for _, obj in ipairs(Workspace:GetChildren()) do                 if obj.Name == "CoinContainer" or obj.Name == "Coin" then                     for _, coin in ipairs(obj:GetChildren()) do                         if coin:IsA("BasePart") and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then                             LocalPlayer.Character.HumanoidRootPart.CFrame = coin.CFrame                             task.wait(0.05)                         end                     end                 end             end         end)     end      if espEnabled then         for _, p in ipairs(Players:GetPlayers()) do             if p ~= LocalPlayer and p.Character then                 local char = p.Character                 local highlight = char:FindFirstChild("LatifahESP")                 if not highlight then                     highlight = Instance.new("Highlight")                     highlight.Name = "LatifahESP"   